import { stdout } from std.io;
class Child {
    v: Int32;
    construct(v: Int32) { this.v = v; }
}
class Parent {
    left: Child;
    right: Child;
    construct(c: Child) { this.left = c; this.right = c; }
}
fn main(): Void {
    mut c = Child(1);
    mut p = Parent(c);
    mut q = p.clone();
    stdout.println(p.left is p.right);
    stdout.println(q.left is q.right);
    stdout.println(q.left is p.left);
    q.left.v = 5;
    stdout.println(q.right.v);
    stdout.println(p.left.v);
}
